// Exercise 14.26c. Define subscript operators for your StrVec, String, StrBlob, and StrBlobPtr classes.

#ifndef MY_STRING_H
#define MY_STRING_H

#include <iostream>
#include <memory>
#include <cstring>

class String {
    friend std::istream& operator>>(std::istream &, String &);
    friend std::ostream& operator<<(std::ostream &, const String &);
    friend bool operator==(const String &, const String &);
    friend bool operator!=(const String &, const String &);
    friend bool operator<(const String &, const String &);
    public:
        String() = default;
        String(const char *);
        String(const String &);
        String(String &&) noexcept;
        String& operator=(const String &);
        String& operator=(String &&) noexcept;
        ~String() { free(); }
        void push_back(const char &);
        void push_back(char &&);
        void pop_back();
        size_t size() const { return first_free - elements; }
        size_t capacity() const { return cap - elements; }
        char *begin() const { return elements; }
        char *end() const { return first_free; }
        void reserve(const size_t &n) { if (n > capacity()) reallocate(n); }
        void resize(const size_t &, const char &ch = '\0');
        char &operator[](std::size_t n) {return elements[n]; }
        const char &operator[](std::size_t n) const {return elements[n]; }
    private:
        static std::allocator<char> alloc;
        void chk_n_alloc() { if (size() == capacity()) reallocate(); }
        std::pair<char *, char *> alloc_n_copy(const char *, const char *);
        void reallocate(const size_t &n = 0);
        void free();
        char *elements{nullptr};
        char *first_free{nullptr};
        char *cap{nullptr};
};

// static members
std::allocator<char> String::alloc;

// constructors
String::String(const char *s)
{
    auto data = alloc_n_copy(s, s + std::strlen(s));
    elements = data.first; 
    first_free = cap = data.second;
}

// copy-controls functions
String::String(const String &s)
{
    auto newdata = alloc_n_copy(s.begin(), s.end());
    elements = newdata.first;
    first_free = cap = newdata.second;
    std::cout << "String(const String &)\n";
}

String::String(String &&s) noexcept : elements(s.elements),
    first_free(s.first_free), cap(s.cap)
{
    s.elements = s.first_free = cap = nullptr;
    std::cout << "String(String &&rhs)\n";
}

String&
String::operator=(const String &rhs)
{
    auto newdata = alloc_n_copy(rhs.begin(), rhs.end());
    free();
    elements = newdata.first;
    first_free = cap = newdata.second;
    return *this;
    std::cout << "String& operator=(const String &)\n";
}

String&
String::operator=(String &&rhs) noexcept
{
    if (this != &rhs) {
        free();
        elements = rhs.elements;
        first_free = rhs.first_free;
        cap = rhs.cap;
        elements = first_free = cap = nullptr;
    }
    std::cout << "String& operator=(String &&rhs)\n";
    return *this;
}

// member functions
void
String::push_back(const char &ch)
{
    chk_n_alloc();
    alloc.construct(first_free++, ch);
}

void
String::push_back(char &&ch)
{
    chk_n_alloc();
    alloc.construct(first_free++, std::move(ch));
}

void
String::pop_back()
{
    if (first_free == elements)
        throw std::out_of_range("pop on empty String");
    alloc.destroy(--first_free);
}

std::pair<char *, char *>
String::alloc_n_copy(const char *b, const char *e)
{
    auto data = alloc.allocate(e - b);
    return {data, std::uninitialized_copy(b, e, data)};
}

void
String::reallocate(const size_t &n)
{
    auto newcapacity = (n) ? n : (size()) ? 2 * size() : 1;
    auto newdata = alloc.allocate(newcapacity);
    auto dest = newdata;
    auto elem = elements;
    for (size_t i = 0; i != size(); ++i)
        alloc.construct(dest++, std::move(*elem++));
    free();
    elements = newdata;
    first_free = dest;
    cap = elements + newcapacity;
}

void
String::free()
{
    for (auto &p = first_free; p != elements;)
        alloc.destroy(--p);
    alloc.deallocate(elements, capacity());
}

void
String::resize(const size_t &n, const char &ch)
{
    reserve(n);
    auto newsize = first_free + (n - size());
    while (first_free != newsize)
        if (first_free < newsize)
            alloc.construct(first_free++, ch);
        else
            alloc.destroy(--first_free);
}

// non-member functions
std::istream& operator>>(std::istream &is, String &s)
{
    std::string input;
    is >> input;
    if (is)
        for (const auto &ch : input)
            s.push_back(std::move(ch));
    return is;
}

std::ostream& operator<<(std::ostream &os, const String &s)
{
    for (const auto &ch : s)
        os << ch; 
    return os;
}

bool operator==(const String &lhs, const String &rhs)
{
    bool result = false;
    if (lhs.size() == rhs.size()) {
        result = true;
        auto rhsP = rhs.begin();
        for (const auto &ch : lhs)
            if (ch != *rhsP++) {
                result = false;
                break;
            }
    }
    return result;
}

bool operator!=(const String &lhs, const String &rhs)
{
    return !(lhs == rhs);
}

// using dictionary ordering
bool operator<(const String &lhs, const String &rhs)
{
    if (lhs.size() == rhs.size()) {
        auto rhsP = rhs.begin();
        for (auto const &ch : lhs) {
            if (ch != *rhsP)
                return ch < *rhsP;
            ++rhsP;
        }
    }
    return lhs.size() < rhs.size();
}
